import{_ as t,o,c as a,a3 as s}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"The xclang Command","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"The xclang Command | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/xclang-command"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/xclang-command"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/xclang-command"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/xclang-command"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/reference/xclang-command"}]]},"headers":[],"relativePath":"xclang/reference/xclang-command.md","filePath":"en/xclang/reference/xclang-command.md","lastUpdated":1794509097000}'),d={name:"xclang/reference/xclang-command.md"};function n(c,e,i,r,h,l){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="the-xclang-command" tabindex="-1">The xclang Command <a class="header-anchor" href="#the-xclang-command" aria-label="Permalink to &quot;The xclang Command&quot;">​</a></h1><p><code>xclang</code> fetches what the toolchain does not carry, the vendor SDKs that cannot be redistributed, and runs cargo with the toolchain as the C compiler and linker of its targets. Every toolchain archive carries it, as <code>bin/xclang</code> (<code>xclang.exe</code> on Windows). Why SDKs are fetched and not shipped is in <a href="./../guide/cross-compiling">cross-compiling</a>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xclang sdk list [macos|windows]</span></span>
<span class="line"><span>xclang sdk fetch macos --accept-license [--preset P] [--version V]</span></span>
<span class="line"><span>xclang sdk fetch windows --accept-license [--preset P] [--msvc-version V] [--sdk-version V] [--arch x86_64,aarch64,x86]</span></span>
<span class="line"><span>xclang sdk path macos|windows [the selection options of fetch]</span></span>
<span class="line"><span>xclang sdk packages macos|windows [the selection options of fetch] [--json]</span></span>
<span class="line"><span>xclang sdk use &lt;name&gt;</span></span>
<span class="line"><span>xclang sdk remove &lt;name&gt;</span></span>
<span class="line"><span>xclang target list</span></span>
<span class="line"><span>xclang target add &lt;target&gt;...</span></span>
<span class="line"><span>xclang target remove &lt;target&gt;...</span></span>
<span class="line"><span>xclang cargo &lt;cargo&#39;s arguments&gt;</span></span>
<span class="line"><span>xclang --version</span></span></code></pre></div><h2 id="vendor-sdks" tabindex="-1">Vendor SDKs <a class="header-anchor" href="#vendor-sdks" aria-label="Permalink to &quot;Vendor SDKs&quot;">​</a></h2><p><code>xclang sdk fetch</code> downloads an SDK from its vendor. It checks each download against the size and sha256 its version table pins, with three tries, since a download now and then comes short or damaged. A macOS SDK whose package Apple withdrew, it finds in another package Apple&#39;s catalogs list, checked by the SDK&#39;s content (<a href="./../design/macos#packages-apple-withdraws-and-content-digests">why</a>). Then it unpacks the SDK into a directory of its own:</p><table tabindex="0"><thead><tr><th>SDK</th><th>directory</th><th>use</th></tr></thead><tbody><tr><td>macOS</td><td><code>$XCLANG/sdk/macos-&lt;version&gt;</code></td><td><code>clang++ --target=arm64-apple-macos</code> on Linux and Windows hosts (<a href="./../guide/cross-compiling#on-linux-and-windows-hosts">macOS</a>); on macOS hosts, and for an SDK outside the toolchain, <code>-isysroot &lt;dir&gt;</code></td></tr><tr><td>MSVC and the Windows SDK</td><td><code>$XCLANG/sdk/windows-msvc&lt;version&gt;-sdk&lt;version&gt;</code></td><td><code>clang++ --target=x86_64-pc-windows-msvc</code>, <code>clang-cl</code>: the <a href="./../guide/cross-compiling#msvc-targets">MSVC targets</a></td></tr></tbody></table><table tabindex="0"><thead><tr><th>command or option</th><th></th></tr></thead><tbody><tr><td><code>--accept-license</code></td><td>without it, fetch prints the vendor&#39;s license terms and stops</td></tr><tr><td><code>sdk path</code></td><td>prints the directory that fetch, given the same selection options (<code>--preset</code>, <code>--version</code>, <code>--msvc-version</code>, <code>--sdk-version</code>, <code>--arch</code>), fetches to: <code>-isysroot &quot;$(xclang sdk path macos)&quot;</code>. With <code>--arch</code>, it fails if the SDK there lacks one of those architectures</td></tr><tr><td><code>sdk packages</code></td><td>prints what fetch, given the same selection options, downloads for an SDK not fetched yet: each package&#39;s sha256, size and URL, or with <code>--json</code> <code>{&quot;name&quot;: &lt;the SDK&#39;s directory&gt;, &quot;packages&quot;: [{&quot;url&quot;, &quot;size&quot;, &quot;sha256&quot;, &quot;file&quot;}]}</code>. A build system downloads them itself, under the names <code>file</code>, into a directory that <code>fetch --cache</code> then takes them from; the Bazel module does (<a href="./../integrations/bazel#build-for-msvc-and-for-macos-anywhere">Bazel</a>). What it cannot download, a package Apple withdrew or one with no sha256 (<code>--version latest</code> past the table), fetch downloads itself</td></tr><tr><td><code>--cache &lt;dir&gt;</code></td><td>fetch keeps its downloads in the directory, and takes from it those already there, by their sha256</td></tr><tr><td><code>sdk list</code></td><td>the presets and versions xclang knows, the defaults marked, the fetched SDKs, and those in use; <code>.xclang-sdk.json</code>, written last, records what an SDK was fetched from, and a directory without it is listed as incomplete</td></tr><tr><td><code>sdk use &lt;name&gt;</code></td><td>makes a fetched SDK the one in use (below)</td></tr><tr><td><code>sdk remove &lt;name&gt;</code></td><td>removes a fetched SDK, and its link if it is in use</td></tr><tr><td><code>--preset &lt;image&gt;</code></td><td>the SDK versions of a GitHub runner image or label (<code>windows-2022</code>, <code>macos-15</code>); by default <code>windows-latest</code> and <code>macos-latest</code></td></tr><tr><td><code>--version</code>, <code>--sdk-version</code>, <code>--msvc-version</code></td><td>a version, whole or in part (<code>15</code>, <code>10.0.26100</code>, <code>14.44</code>), in place of the preset&#39;s; the newest that matches is taken. <code>--version latest</code> takes the newest macOS SDK Apple&#39;s catalogs list now, which may be newer than the table, and is not reproducible</td></tr><tr><td><code>--arch &lt;archs&gt;</code></td><td>the architectures of a Windows SDK, of <code>x86_64</code>, <code>aarch64</code> and <code>x86</code>; by default <code>x86_64,aarch64</code>. Fetched again, an SDK keeps the architectures it has: <code>--arch x86</code> adds x86</td></tr><tr><td><code>--sdk-dir &lt;dir&gt;</code></td><td>another directory for SDKs, for a toolchain installed read-only</td></tr><tr><td><code>--links &lt;how&gt;</code></td><td>how fetch makes the macOS SDK&#39;s links: <code>junction</code>, junctions and hard links, the default on Windows; <code>symlink</code>, symbolic links, the default elsewhere; or <code>copy</code></td></tr><tr><td><code>--root &lt;dir&gt;</code></td><td>the toolchain the command acts on; by default the one it is in</td></tr></tbody></table><p>Fetching an SDK that is there already unpacks it anew, and keeps the old one aside, as <code>.&lt;name&gt;.old</code>, until the new one is whole. If the fetch fails, the old one is put back, and stays usable. An interrupted fetch leaves that to the next one. The disk needs room for both meanwhile. If the old one cannot be moved aside, as on Windows while a program has one of its files open, the fetch stops, and the SDK stays as it was.</p><h3 id="the-sdk-in-use" tabindex="-1">The SDK in Use <a class="header-anchor" href="#the-sdk-in-use" aria-label="Permalink to &quot;The SDK in Use&quot;">​</a></h3><p>The SDK fetched last, or the one <code>sdk use</code> names, is the one in use: <code>$XCLANG/sdk/windows</code> and <code>$XCLANG/sdk/macos</code> point to it, a symbolic link, or on Windows a junction, which needs no privilege. That gives the config files a fixed path. A Windows SDK holds a config file per architecture fetched and per driver, <code>&lt;arch&gt;-pc-windows-msvc.cfg</code> and <code>&lt;arch&gt;-pc-windows-msvc-clang-cl.cfg</code>, which name the SDK and its versions. The MSVC targets&#39; own config files read them through <code>bin/&lt;arch&gt;-pc-windows-msvc-sdk.cfg</code> and <code>bin/&lt;arch&gt;-pc-windows-msvc-clang-cl-sdk.cfg</code>, which <code>fetch</code>, <code>use</code> and <code>remove</code> rewrite: they include the files of the SDK in use, through <code>sdk/windows</code>, or say there is none for the architecture (<a href="./../guide/cross-compiling#msvc-targets">why</a>). An update of a conda package writes them anew, naming none; <code>sdk use</code> names the SDK again. On Linux and macOS hosts the config files read <code>sdk/windows</code> meanwhile all the same. On Linux and Windows hosts the macOS targets&#39; config files name <code>sdk/macos</code> as their <code>-isysroot</code> (<a href="./../guide/cross-compiling#on-linux-and-windows-hosts">why</a>); on macOS hosts they use Xcode&#39;s SDK, and a fetched one takes <code>-isysroot</code>. An SDK fetched with <code>--sdk-dir</code> is outside the toolchain, where its config files do not look.</p><p>On Windows, a junction holds an absolute path. When the toolchain directory moves, <code>xclang sdk use &lt;name&gt;</code> points <code>sdk/windows</code> or <code>sdk/macos</code> to the SDK at its new place again. A macOS SDK fetched with junctions, the default on Windows, has more of them inside: fetch it again after the move, or fetch it with <code>--links copy</code>, which makes none.</p><h3 id="versions" tabindex="-1">Versions <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;Versions&quot;">​</a></h3><p><code>xclang/sdk-versions.json</code>, built into the program, lists every version the vendors offer:</p><ul><li>the Windows SDKs on NuGet;</li><li>the MSVC toolsets of the Visual Studio channels;</li><li>the macOS SDK packages of Apple&#39;s software update catalogs;</li><li>presets: the versions GitHub&#39;s runner images build with, so a cross build matches what a workflow gets. <code>windows-2022</code> has MSVC 14.44, whose STL still serves Windows 7 SP1 and 8.1.</li></ul><p>With no version given, the preset&#39;s is taken.</p><h3 id="what-is-fetched" tabindex="-1">What Is Fetched <a class="header-anchor" href="#what-is-fetched" aria-label="Permalink to &quot;What Is Fetched&quot;">​</a></h3><p><strong>macOS</strong> comes from a Command Line Tools package on <code>swcdn.apple.com</code>, without an Apple ID. Man pages, tools and Perl are left out. On Windows, symlinks become junctions (to directories) and hard links (to files), which need no privilege. The download is 62 MB, 610 MB unpacked.</p><p><strong>Windows</strong> comes from the <code>.vsix</code> packages of Visual Studio and NuGet&#39;s <code>Microsoft.Windows.SDK.CPP</code> packages, laid out as a <code>/winsysroot</code>, as Visual Studio installs it. The <code>.vsix</code> packages hold the CRT and STL: the headers, the STL&#39;s <code>std</code> modules (<code>std.ixx</code>), and per architecture the libraries of the static and DLL runtimes, with the PDBs of the static runtime. A debug link looks for those, and warns without them (LNK4099). On a case-sensitive file system, 3.6k links are added for the spellings Windows code uses. The download is 600 MB for x64 and arm64, 1.8 GB unpacked.</p><h2 id="targets" tabindex="-1">Targets <a class="header-anchor" href="#targets" aria-label="Permalink to &quot;Targets&quot;">​</a></h2><p><code>xclang target list</code> lists the targets of the release, all of them built into the toolchain. <code>xclang target add</code> and <code>target remove</code> add and remove targets that the release publishes as archives of their own, and no release publishes any yet (<a href="./../design/roadmap#target-archives">target archives</a>).</p><h2 id="cargo" tabindex="-1">cargo <a class="header-anchor" href="#cargo" aria-label="Permalink to &quot;cargo&quot;">​</a></h2><p><code>xclang cargo build --target &lt;Rust target&gt;</code>, and cargo&#39;s other commands, run cargo with the variables of the targets it builds for set: those of <code>--target</code>, of <code>build.target</code>, or the host&#39;s. The linker of each target is <code>xclang</code> itself, under the name <code>&lt;Rust target&gt;-linker</code> in xclang&#39;s cache directory, which runs clang (lld-link for the MSVC targets) with what the target needs. A target&#39;s missing standard library is added with <code>rustup target add</code>; a missing vendor SDK is named, with its <code>xclang sdk fetch</code>. What it sets, target by target, is in <a href="./../integrations/cargo#what-xclang-cargo-sets">Rust and Cargo</a>.</p><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><p>Every request says <code>User-Agent: xclang/&lt;version&gt;</code>, and nothing else about the user. TLS is rustls, with ring. Certificates are checked against the trust store of the system: Security.framework on macOS, the certificate store on Windows, the CA files of a Linux system. So a CA that a company installs is trusted too. A Linux system without CA files falls back to Mozilla&#39;s roots.</p><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>variable</th><th></th></tr></thead><tbody><tr><td><code>XCLANG_ROOT</code></td><td>the toolchain, as <code>--root</code></td></tr><tr><td><code>XCLANG_SDK_DIR</code></td><td>another directory for SDKs, as <code>--sdk-dir</code></td></tr><tr><td><code>XCLANG_JOBS</code></td><td>how many threads unpack; one per CPU by default</td></tr><tr><td><code>XCLANG_TARGET_INDEX</code></td><td>another target index, as <code>--index</code></td></tr><tr><td><code>XCLANG_CACHE_DIR</code></td><td>where <code>xclang cargo</code> keeps its linkers and CMake toolchain files; by default <code>xclang</code> in the user&#39;s cache directory</td></tr><tr><td><code>XCLANG_STDLIB</code></td><td><code>platform</code>: <code>xclang cargo</code> builds C++ with the platform&#39;s C++ library (<a href="./../integrations/cargo#the-system-s-c-library">Rust and Cargo</a>)</td></tr><tr><td><code>HTTPS_PROXY</code>, <code>HTTP_PROXY</code>, <code>ALL_PROXY</code>, <code>NO_PROXY</code></td><td>honoured</td></tr><tr><td><code>SSL_CERT_FILE</code></td><td>a CA file, read on Linux</td></tr></tbody></table>`,26)])])}const m=t(d,[["render",n]]);export{p as __pageData,m as default};
